# Check primality-based transformation
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            return False
    return True

input_grid = [[1, 2, 5], [7, 3, 6], [7, 6, 5]]

# Maybe output marks primes with 1 and non-primes with 0?
prime_output = []
for row in input_grid:
    prime_output.append([1 if is_prime(cell) else 0 for cell in row])
print("Prime mask:", prime_output)

# Or maybe mark odd/even?
odd_even = []
for row in input_grid:
    odd_even.append([1 if cell % 2 == 1 else 0 for cell in row])
